import re
from typing import Dict, List, Tuple


def parse_script(text: str) -> Dict:
    """
    Parse a dialogue script into a structured graph.

    Args:
        text: The script text to parse

    Returns:
        Dictionary with 'nodes' and 'edges' keys
    """
    nodes = []
    edges = []

    # Split text into lines and process
    lines = text.split('\n')
    current_scene = None
    scene_content = []

    # First pass: identify all scenes and their content
    scenes = {}

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Check if this is a scene header
        scene_match = re.match(r'\[([^\]]+)\]', line)
        if scene_match:
            # Save previous scene if exists
            if current_scene:
                scenes[current_scene] = scene_content

            # Start new scene
            current_scene = scene_match.group(1)
            scene_content = []
        elif current_scene:
            scene_content.append(line)

    # Don't forget the last scene
    if current_scene:
        scenes[current_scene] = scene_content

    # Collect all referenced node IDs
    referenced_nodes = set(scenes.keys())

    # Second pass: create edges and collect all referenced nodes
    for scene_name, content in scenes.items():
        if not content:
            continue

        is_choice = False

        # Check if it's a choice
        if re.match(r'^\d+\.', content[0]):
            is_choice = True

