                    referenced_nodes.add(target)
                    edge_text = f"{num}. {choice_text}"
                    edge = {
                        "from": scene_name,
                        "to": target,
                        "text": edge_text
                    }
                    edges.append(edge)
        else:
            # Single line - check for edge
            match = re.match(r'^([^:]+):\s*(.+?)(?:\s*->\s*(.+))?$', content[0])
            if match:
                speaker = match.group(1).strip()
                text = match.group(2).strip()
                target = match.group(3)

                if target:
                    referenced_nodes.add(target)
                    edge = {
                        "from": scene_name,
                        "to": target,
                        "text": ""
                    }
                    edges.append(edge)

    # Process each scene to create nodes
    for scene_name, content in scenes.items():
        # Determine if this is a line or choice node
        # Choice nodes have numbered options
        # Line nodes have speaker:text format

        is_choice = False
        speaker = None
        text = ""

        if content:
            # Check if it's a choice (starts with number)
            if re.match(r'^\d+\.', content[0]):
                is_choice = True
                # Collect all choice options
                text_parts = []
                for line in content:
                    # Extract the text before ->
                    match = re.match(r'^(\d+)\.\s*(.+?)\s*->\s*', line)
                    if match:
                        num, choice_text = match.groups()
                        text_parts.append(f"{num}. {choice_text}")

                text = '\n'.join(text_parts)
            else:
                # It's a line with dialogue
                # Take the first line as the main text
                match = re.match(r'^([^:]+):\s*(.+?)(?:\s*->\s*.*)?$', content[0])
                if match:
                    speaker = match.group(1).strip()
                    text = match.group(2).strip()
                else:
                    speaker = "Narrator"
                    text = content[0]

        # Create node
        node_type = "choice" if is_choice else "line"
        node = {
            "id": scene_name,
            "text": text,
            "speaker": speaker if speaker else "",
            "type": node_type
        }
        nodes.append(node)

    # Create nodes for referenced but undefined nodes (like "End")
    for node_id in referenced_nodes:
        if node_id not in scenes:
            node = {
                "id": node_id,
                "text": "The End",
                "speaker": "",
                "type": "line"
            }
            nodes.append(node)

    # Second pass: create edges
    for scene_name, content in scenes.items():
