    return {"nodes": nodes, "edges": edges}


def validate_graph(graph: Dict) -> Tuple[bool, List[str]]:
    """
    Validate the graph structure.
    Returns (is_valid, list_of_errors)
    """
    errors = []

    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    if not nodes:
        errors.append("No nodes in graph")
        return False, errors

    # Build set of node IDs
    node_ids = {node["id"] for node in nodes}

    # Check 1: All nodes must be reachable from the first node
    # Find the first node (typically "Start")
    first_node = None
    for node in nodes:
        if node["id"] == "Start":
            first_node = node["id"]
            break

    if not first_node:
        # If no "Start", use the first node
        first_node = nodes[0]["id"] if nodes else None

    if first_node:
        # BFS to find reachable nodes
        reachable = set()
        queue = [first_node]
        adjacency = {}

        # Build adjacency list
        for edge in edges:
            if edge["from"] not in adjacency:
                adjacency[edge["from"]] = []
            adjacency[edge["from"]].append(edge["to"])

        while queue:
            current = queue.pop(0)
            if current not in reachable:
                reachable.add(current)
                if current in adjacency:
                    for neighbor in adjacency[current]:
                        if neighbor not in reachable:
                            queue.append(neighbor)

        # Check reachability
        unreachable = node_ids - reachable
        if unreachable:
            errors.append(f"Unreachable nodes: {unreachable}")

    # Check 2: All edge targets must exist (except for "End" nodes)
    for edge in edges:
        target = edge["to"]
        # Allow edges to "End" or empty targets
        if target and target not in node_ids:
            errors.append(f"Edge from '{edge['from']}' points to non-existent node '{target}'")

    return len(errors) == 0, errors


def generate_dot(graph: Dict, output_path: str):
    """
    Generate a DOT file for graph visualization.
    """
    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    with open(output_path, 'w') as f:
        f.write("digraph Dialogue {\n")
        f.write("    rankdir=LR;\n")
        f.write("    node [shape=box, style=rounded];\n\n")

        # Define node styles
        for node in nodes:
            node_id = node["id"]
            node_type = node["type"]

            # Different shapes for different node types
            if node_type == "choice":
                shape = "diamond"
            else:
                shape = "box"

            # Escape quotes in text
            text = node["text"].replace('"', '\\"')[:50]  # Limit text length
            speaker = node["speaker"] if node["speaker"] else ""

            if speaker:
                label = f"{speaker}:\\n{text}"
            else:
                label = text

            f.write(f'    "{node_id}" [label="{label}", shape={shape}];\n')

        f.write("\n")

        # Define edges
        for edge in edges:
            from_node = edge["from"]
            to_node = edge["to"]
            edge_text = edge["text"]

            # Escape quotes
            edge_text = edge_text.replace('"', '\\"')

            if edge_text:
                f.write(f'    "{from_node}" -> "{to_node}" [label="{edge_text}"];\n')
            else:
                f.write(f'    "{from_node}" -> "{to_node}";\n')

        f.write("}\n")


if __name__ == "__main__":
    # Read the script
    with open('/app/script.txt', 'r') as f:
        script_text = f.read()

    # Parse the script
    graph = parse_script(script_text)

    # Validate the graph
    is_valid, errors = validate_graph(graph)

    if not is_valid:
        print("Validation errors:")
        for error in errors:
